import{_ as t,o,c as a,l as i,t as n,N as s}from"./chunks/framework.Bbd9fWQx.js";const b=JSON.parse('{"title":"git-imap-send | x-cmd man (git man1) | Send a collection of patches from stdin to an IMAP\\nfolder","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-imap-send - Send a collection of patches from stdin to an IMAP\\nfolder","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-imap-send | x-cmd man (git man1) | Send a collection of patches from stdin to an IMAP\\nfolder"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-imap-send - Send a collection of patches from stdin to an IMAP\\nfolder"}]]},"headers":[],"params":{"isMan":true,"man":"git-imap-send","category":"git man1","desc":"Send a collection of patches from stdin to an IMAP\\nfolder"},"relativePath":"git/man1/git-imap-send.md","filePath":"git/man1/git-imap-send.md"}'),r={name:"git/man1/git-imap-send.md"},l={class:"visually-hidden"},p=s(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-imap-send - Send a collection of patches from stdin to an IMAP folder</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> imap-send</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-v] [-q] [--[no-]curl]</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>This command uploads a mailbox generated with <em>git format-patch</em> into an IMAP drafts folder. This allows patches to be sent as other email is when using mail clients that cannot read mailbox files directly. The command also works with any general mailbox in which emails have the fields &quot;From&quot;, &quot;Date&quot;, and &quot;Subject&quot; in that order.</p><p>Typical usage is something like:</p><p>git format-patch --signoff --stdout --attach origin | git imap-send</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>-v, --verbose</p><blockquote><p>Be verbose.</p></blockquote><p>-q, --quiet</p><blockquote><p>Be quiet.</p></blockquote><p>--curl</p><blockquote><p>Use libcurl to communicate with the IMAP server, unless tunneling into it. Ignored if Git was built without the USE_CURL_FOR_IMAP_SEND option set.</p></blockquote><p>--no-curl</p><blockquote><p>Talk to the IMAP server using git&#39;s own IMAP routines instead of using libcurl. Ignored if Git was built with the NO_OPENSSL option set.</p></blockquote><h2 id="configuration" tabindex="-1">CONFIGURATION <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;CONFIGURATION&quot;">​</a></h2><p>To use the tool, <strong>imap.folder</strong> and either <strong>imap.tunnel</strong> or <strong>imap.host</strong> must be set to appropriate values.</p><p>Everything above this line in this section isn&#39;t included from the <strong>git-config</strong>(1) documentation. The content that follows is the same as what&#39;s found there:</p><p>imap.folder</p><blockquote><p>The folder to drop the mails into, which is typically the Drafts folder. For example: &quot;INBOX.Drafts&quot;, &quot;INBOX/Drafts&quot; or &quot;[Gmail]/Drafts&quot;. Required.</p></blockquote><p>imap.tunnel</p><blockquote><p>Command used to setup a tunnel to the IMAP server through which commands will be piped instead of using a direct network connection to the server. Required when imap.host is not set.</p></blockquote><p>imap.host</p><blockquote><p>A URL identifying the server. Use an <strong>imap://</strong> prefix for non-secure connections and an <strong>imaps://</strong> prefix for secure connections. Ignored when imap.tunnel is set, but required otherwise.</p></blockquote><p>imap.user</p><blockquote><p>The username to use when logging in to the server.</p></blockquote><p>imap.pass</p><blockquote><p>The password to use when logging in to the server.</p></blockquote><p>imap.port</p><blockquote><p>An integer port number to connect to on the server. Defaults to 143 for imap:// hosts and 993 for imaps:// hosts. Ignored when imap.tunnel is set.</p></blockquote><p>imap.sslverify</p><blockquote><p>A boolean to enable/disable verification of the server certificate used by the SSL/TLS connection. Default is <strong>true</strong>. Ignored when imap.tunnel is set.</p></blockquote><p>imap.preformattedHTML</p><blockquote><p>A boolean to enable/disable the use of html encoding when sending a patch. An html encoded patch will be bracketed with &lt;pre&gt; and have a content type of text/html. Ironically, enabling this option causes Thunderbird to send the patch as a plain/text, format=fixed email. Default is <strong>false</strong>.</p></blockquote><p>imap.authMethod</p><blockquote><p>Specify authenticate method for authentication with IMAP server. If Git was built with the NO_CURL option, or if your curl version is older than 7.34.0, or if you&#39;re running git-imap-send with the <strong>--no-curl</strong> option, the only supported method is <em>CRAM-MD5</em>. If this is not set then <em>git imap-send</em> uses the basic IMAP plaintext LOGIN command.</p></blockquote><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p>Using tunnel mode:</p><blockquote><pre><code>[imap]
    folder = &quot;INBOX.Drafts&quot;
    tunnel = &quot;ssh -q -C user@example.com /usr/bin/imapd ./Maildir 2&gt; /dev/null&quot;
</code></pre></blockquote><p>Using direct mode:</p><blockquote><pre><code>[imap]
    folder = &quot;INBOX.Drafts&quot;
    host = imap://imap.example.com
    user = bob
    pass = p4ssw0rd
</code></pre></blockquote><p>Using direct mode with SSL:</p><blockquote><pre><code>[imap]
    folder = &quot;INBOX.Drafts&quot;
    host = imaps://imap.example.com
    user = bob
    pass = p4ssw0rd
    port = 123
    ; sslVerify = false
</code></pre></blockquote><blockquote><p><br> &gt; <strong>Note</strong></p><p><br> &gt; You may want to use <strong>sslVerify=false</strong> while troubleshooting, if you suspect that the reason you are having trouble connecting is because the certificate you use at the private server <strong>example.com</strong> you are trying to set up (or have set up) may not be verified correctly.</p></blockquote><p>Using Gmail&#39;s IMAP interface:</p><blockquote><pre><code>[imap]
        folder = &quot;[Gmail]/Drafts&quot;
        host = imaps://imap.gmail.com
        user = user@gmail.com
        port = 993
</code></pre></blockquote><blockquote><p><br> &gt; <strong>Note</strong></p><p><br> &gt; You might need to instead use: <strong>folder = &quot;[Google Mail]/Drafts&quot;</strong> if you get an error that the &quot;Folder doesn&#39;t exist&quot;.</p></blockquote><blockquote><p><br> &gt; <strong>Note</strong></p><p><br> &gt; If your Gmail account is set to another language than English, the name of the &quot;Drafts&quot; folder will be localized.</p></blockquote><p>Once the commits are ready to be sent, run the following command:</p><blockquote><pre><code>$ git format-patch --cover-letter -M --stdout origin/master | git imap-send
</code></pre></blockquote><p>Just make sure to disable line wrapping in the email client (Gmail&#39;s web interface will wrap lines no matter what, so you need to use a real IMAP client).</p><h2 id="caution" tabindex="-1">CAUTION <a class="header-anchor" href="#caution" aria-label="Permalink to &quot;CAUTION&quot;">​</a></h2><p>It is still your responsibility to make sure that the email message sent by your email program meets the standards of your project. Many projects do not like patches to be attached. Some mail agents will transform patches (e.g. wrap lines, send them as format=flowed) in ways that make them fail. You will get angry flames ridiculing you if you don&#39;t check this.</p><p>Thunderbird in particular is known to be problematic. Thunderbird users may wish to visit this web page for more information: <strong><a href="http://kb.mozillazine.org/Plain_text_e-mail%5C_-%5C_Thunderbird#Completely_plain_email" target="_blank" rel="noreferrer">http://kb.mozillazine.org/Plain_text_e-mail\\_-\\_Thunderbird#Completely_plain_email</a></strong></p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>git-format-patch</strong>(1), <strong>git-send-email</strong>(1), mbox(5)</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,60);function c(e,h,u,d,m,g){return o(),a("div",null,[i("h1",l,n(e.$params.man),1),p])}const q=t(r,[["render",c]]);export{b as __pageData,q as default};
